window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[220]={"id":"220","numero":220,"titre":"Adénopathies superficielles","objectifs":[{"id":"220-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les circonstances de découverte d’une adénopathie superficielle de l’enfant","contenu":"<p>L'<span class=\"kw-def\">adénopathie</span> est un <strong>ganglion lymphatique hypertrophié</strong> : son diagnostic est <strong>clinique</strong>, posé à la palpation. L'organisme compte <span class=\"kw-chiffre\">200 à 300</span> ganglions, organes de <span class=\"kw-ttt\">drainage</span> de la lymphe d'un territoire anatomique.</p>\n      <p>Le seuil de taille considéré comme <span class=\"kw-alerte\">pathologique</span> est <span class=\"kw-chiffre\">&gt; 1 cm</span>, sauf en région <strong>inguinale</strong> où il est de <span class=\"kw-chiffre\">&gt; 2 cm</span>. Ce seuil n'est ni un <span class=\"kw-def\">critère de</span> bénignité ni un critère de malignité.</p>\n      <table >\n        <thead><tr><th>Circonstance</th><th>Contexte</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Découverte fortuite</strong></td><td>Palpation par l'<span class=\"kw-clinique\">enfant</span> lui-même ou par les <span class=\"kw-clinique\">parents</span> (cou, aisselle, aine)</td></tr>\n          <tr><td><strong>Examen pédiatrique systématique</strong></td><td>Palpation des aires ganglionnaires lors d'une consultation de routine</td></tr>\n          <tr><td><strong>Épisode <span class=\"kw-etio\">infectieux</span></strong></td><td>Bilan d'une <span class=\"kw-etio\">infection ORL</span> ou cutanée de voisinage</td></tr>\n          <tr><td><strong>Signes généraux</strong></td><td>Découverte devant une <span class=\"kw-clinique\">fièvre</span>, un <span class=\"kw-clinique\">amaigrissement</span>, une <span class=\"kw-clinique\">asthénie</span></td></tr>\n          <tr><td><strong>Complication révélatrice</strong></td><td>Phénomène compressif, <span class=\"kw-clinique\">masse</span> volumineuse</td></tr>\n        </tbody>\n      </table>\n      <p>On distingue l'<span class=\"kw-clinique\">adénopathie</span> <span class=\"kw-def\">localisée</span> (un ou plusieurs ganglions d'un <strong>même territoire</strong> de <span class=\"kw-ttt\">drainage</span>) de la <span class=\"kw-def\">polyadénopathie</span> (ganglions de <strong>territoires différents</strong>).</p>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Chez le <strong>sujet jeune</strong>, des polyadénopathies cervicales hautes, <span class=\"kw-clinique\">persistantes</span> et de <strong>petite taille</strong> sont banales : ce <span class=\"kw-def\">terrain</span> est volontiers le siège d'infections à <span class=\"kw-etio\">EBV</span>, <span class=\"kw-etio\">CMV</span> ou <span class=\"kw-etio\">VIH</span>.\n      </div>","frequence":0},{"id":"220-2","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître l’orientation diagnostique d’une adénopathie superficielle de l’enfant","contenu":"<p>Une fois l'<span class=\"kw-clinique\">adénopathie</span> identifiée, l'orientation diagnostique chez l'enfant repose sur un <strong>arbre décisionnel</strong> : recherche d'abord de <span class=\"kw-alerte\">signes d'urgence</span>, puis tri selon le caractère <strong>unique</strong> ou <strong>multiple</strong> de l'atteinte.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/220/cat-adenopathie-superficielle-enfant.png\" alt=\"Arbre décisionnel de conduite à tenir devant une adénopathie superficielle : tri selon signes d'urgence, caractère unique ou multiple, inflammatoire ou non\" loading=\"lazy\">\n        <figcaption>Conduite à tenir devant une <span class=\"kw-clinique\">adénopathie</span> superficielle : arbre décisionnel selon la présence de signes d'<span class=\"kw-alerte\">urgence</span>, le caractère unique ou multiple, <span class=\"kw-etio\">inflammatoire</span> ou non. Source : fiche source EDN item 220 (Fig. 25.1.A).</figcaption>\n      </figure>\n      <table >\n        <thead><tr><th>Situation</th><th>Orientation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Signes d'urgence présents</span></td><td><span class=\"kw-alerte\">Hospitalisation</span> ; enquête (biologie, imagerie) ; <span class=\"kw-bio\">ponction</span> ou <span class=\"kw-bio\">biopsie</span> ganglionnaire</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Adénopathie</span> unique</strong></td><td><strong><span class=\"kw-etio\">Inflammatoire</span> :</strong> <span class=\"kw-etio\">adénite</span> infectieuse, le plus souvent <span class=\"kw-etio\">bactérienne</span> sur foyer de voisinage<br><strong>Non inflammatoire :</strong> bilan de débrouillage ± avis spécialisé selon l'<span class=\"kw-clinique\">évolution</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Adénopathies</span> multiples</strong></td><td><strong>Cause infectieuse :</strong> <span class=\"kw-bio\">sérologies</span> des viroses à tropisme lymphoïde<br><strong>Cause <span class=\"kw-etio\">tumorale</span> :</strong> <span class=\"kw-bio\">hémogramme</span>, frottis, ± myélogramme, cytoponction / <span class=\"kw-bio\">biopsie</span><br><strong>Autres :</strong> examens ciblés selon le contexte</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Repère.</strong> Toute <span class=\"kw-clinique\">adénopathie</span> isolée n'ayant pas fait sa preuve étiologique au bout de <span class=\"kw-chiffre\">4 à 6 semaines</span> impose d'évoquer une <span class=\"kw-def\">hémopathie lymphoïde</span> et de recourir à la <span class=\"kw-bio\">biopsie</span> ganglionnaire.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 315 — Leucémie aiguë · 319 — Lymphome malin</em></p>","frequence":0},{"id":"220-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître l’examen des autres organes lymphoïdes","contenu":"<p>Devant une <span class=\"kw-clinique\">adénopathie</span>, l'examen ne s'arrête pas au ganglion repéré : il explore systématiquement <strong>l'ensemble du tissu lymphoïde</strong>.</p>\n      <table >\n        <thead><tr><th>Organe lymphoïde</th><th>Ce qu'on recherche</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Toutes les aires ganglionnaires</strong></td><td>Palpation des aires <span class=\"kw-clinique\">cervicales</span>, <span class=\"kw-clinique\">sus-claviculaires</span>, <span class=\"kw-clinique\">axillaires</span>, <span class=\"kw-clinique\">épitrochléennes</span> et <span class=\"kw-clinique\">inguinales</span> — préciser le caractère localisé ou diffus</td></tr>\n          <tr><td><strong>Anneau de Waldeyer</strong></td><td><span class=\"kw-clinique\">Hypertrophie amygdalienne</span> à l'examen de l'oropharynx</td></tr>\n          <tr><td><strong>Rate</strong></td><td><span class=\"kw-clinique\">Splénomégalie</span> — atteinte d'un organe lymphoïde profond</td></tr>\n          <tr><td><strong>Foie</strong></td><td><span class=\"kw-clinique\">Hépatomégalie</span> associée</td></tr>\n        </tbody>\n      </table>\n      <p>Une <span class=\"kw-clinique\">adénopathie</span> cervicale justifie en outre un <strong>examen ORL / cervicofacial</strong> complet : <span class=\"kw-clinique\">otoscopie</span>, <span class=\"kw-clinique\">nasofibroscopie pharyngo-laryngée</span>, recherche d'une porte d'entrée des voies aérodigestives supérieures.</p>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> Une <span class=\"kw-alerte\">hypoesthésie de la houppe du menton</span> est très évocatrice d'une <strong>atteinte méningée</strong> dans un contexte d'hémopathie maligne — à rechercher devant toute polyadénopathie suspecte.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 275 — <span class=\"kw-clinique\">Splénomégalie</span></em></p>","frequence":1},{"id":"220-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments d’interrogatoire pour l’orientation étiologique","contenu":"<p>L'interrogatoire oriente fortement l'enquête étiologique. Deux axes : le <strong><span class=\"kw-def\">terrain</span></strong> et les <strong>signes associés</strong>.</p>\n      <table >\n        <thead><tr><th>Élément du terrain</th><th>Orientation</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Âge</strong></td><td><strong>Sujet jeune :</strong> viroses banales — <span class=\"kw-etio\">EBV</span>, <span class=\"kw-etio\">CMV</span>, <span class=\"kw-etio\">VIH</span><br><strong>Sujet âgé :</strong> risque accru de <span class=\"kw-alerte\">cancer</span></td></tr>\n          <tr><td><strong>Antécédents et toxiques</strong></td><td>ATCD, statut vaccinal, traitements en cours, consommation de toxiques</td></tr>\n          <tr><td><strong>Conduites sexuelles</strong></td><td>Rapports à risque → <span class=\"kw-etio\">IST</span> : syphilis, chancre mou, maladie de Nicolas-Favre</td></tr>\n          <tr><td><strong>Contact animalier</strong></td><td>Chat → <span class=\"kw-etio\">maladie des griffes du chat</span> ; gibier → <span class=\"kw-etio\">tularémie</span></td></tr>\n          <tr><td><strong>Voyage</strong></td><td>Zone d'endémie <span class=\"kw-etio\">parasitaire</span> → <span class=\"kw-etio\">leishmaniose viscérale</span> devant une polyadénopathie fébrile au retour</td></tr>\n          <tr><td><strong>Profession / loisirs</strong></td><td>Chasseur, taxidermiste → <span class=\"kw-etio\">tularémie</span> devant une <span class=\"kw-clinique\">adénopathie</span> cervicale</td></tr>\n        </tbody>\n      </table>\n      <p>Les <strong>signes généraux</strong> (« symptômes B ») orientent vers une <span class=\"kw-def\">hémopathie lymphoïde</span> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Fièvre</span> — fait d'abord évoquer une <span class=\"kw-etio\">infection</span> (mais peut manquer dans le <span class=\"kw-etio\">VIH</span>)</li>\n        <li><span class=\"kw-clinique\">Asthénie</span>, <span class=\"kw-clinique\">anorexie</span>, <span class=\"kw-clinique\">amaigrissement</span></li>\n        <li><span class=\"kw-clinique\">Sueurs nocturnes</span>, <span class=\"kw-clinique\">frissons</span></li>\n        <li><span class=\"kw-clinique\">Prurit généralisé</span></li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 159 — <span class=\"kw-def\">Tuberculose</span> Enfant / Adulte</em></p>","frequence":1},{"id":"220-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître l’orientation diagnostique en fonction du contexte et des manifestations associées à une adénopathie de l’adulte et de l’enfant","contenu":"<p>Objectif central de l'item : devant une <span class=\"kw-clinique\">adénopathie</span> de l'adulte ou de l'enfant, l'orientation diagnostique repose sur la <strong>caractérisation sémiologique</strong>, le <strong>territoire de <span class=\"kw-ttt\">drainage</span></strong>, les <strong>manifestations associées</strong> et la lecture de l'<span class=\"kw-bio\">hémogramme</span>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">1 — Caractériser l'<span class=\"kw-clinique\">adénopathie</span> (mnémo ADENOPATA)</h4>\n      <table >\n        <thead><tr><th>Item</th><th>À préciser</th></tr></thead>\n        <tbody>\n          <tr><td><strong>A</strong>ncienneté</td><td>Date, mode de début, durée (certaines sont transitoires)</td></tr>\n          <tr><td><strong>D</strong>ureté</td><td><strong>Molle, fluctuante :</strong> en faveur d'une <span class=\"kw-etio\">suppuration</span><br><strong>Dure, ligneuse, rocailleuse :</strong> en faveur d'un <span class=\"kw-alerte\">cancer</span><br><strong>Ferme, élastique :</strong> bénin comme malin</td></tr>\n          <tr><td><strong>É</strong>tendue</td><td>Diffuse, ou localisée au territoire de <span class=\"kw-ttt\">drainage</span> d'une <span class=\"kw-clinique\">lésion</span></td></tr>\n          <tr><td><strong>N</strong>ombre</td><td>Unique ou multiples</td></tr>\n          <tr><td><strong>O</strong>ù</td><td>Localisation précise (territoire ganglionnaire)</td></tr>\n          <tr><td><strong>P</strong>éri-adénite</td><td>Caractère <span class=\"kw-etio\">inflammatoire</span> (= <span class=\"kw-etio\">adénite</span>) : douleur spontanée ou provoquée, peau rouge, ulcérée ou fistulisée → cause infectieuse</td></tr>\n          <tr><td><strong>A</strong>dhérence</td><td>Adhérence ou non aux plans superficiels et profonds</td></tr>\n          <tr><td><strong>T</strong>aille</td><td><span class=\"kw-chiffre\">&gt; 1 cm</span> (<span class=\"kw-chiffre\">&gt; 2 cm</span> en inguinal) : en général pathologique</td></tr>\n          <tr><td><strong>A</strong>utres</td><td>Douleur à l'ingestion d'<span class=\"kw-etio\">alcool</span> : évocatrice de certains <span class=\"kw-def\">lymphomes de Hodgkin</span></td></tr>\n        </tbody>\n      </table>\n      <p>Signes en faveur d'une <span class=\"kw-alerte\">cause tumorale maligne</span> : consistance dure / ligneuse / rocailleuse ; <strong>ballonisation</strong> (perte de la forme oblongue) ; immobilité par rapport aux plans adjacents ; compression des structures voisines (veines, nerfs).</p>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Il n'existe <span class=\"kw-alerte\">aucun critère sémiologique formel de bénignité</span> d'une <span class=\"kw-clinique\">adénopathie</span>. Une <span class=\"kw-clinique\">adénopathie</span> inguinale de <span class=\"kw-chiffre\">2 cm</span>, non douloureuse et non indurée, peut être physiologique — mais l'absence de signe inquiétant ne rassure jamais à elle seule.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">2 — Territoire de <span class=\"kw-ttt\">drainage</span></h4>\n      <table >\n        <thead><tr><th><span class=\"kw-clinique\">Adénopathie</span></th><th>Territoire drainé</th><th>Étiologies à suspecter</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Cervicale</strong></td><td>Face, cuir chevelu, cavité buccale, dents, sphère ORL, sinus, thyroïde</td><td>Infections ORL, cancers des VADS</td></tr>\n          <tr><td><strong>Sus-claviculaire droite</strong></td><td>Poumon, médiastin</td><td>Cancer thoracique</td></tr>\n          <tr><td><strong>Sus-claviculaire gauche</strong> <span class=\"kw-alerte\">(Troisier)</span></td><td>Canal thoracique → abdomen et pelvis (tube digestif, rein, prostate, testicule)</td><td><span class=\"kw-alerte\">Cancer sous-diaphragmatique</span> ou lymphome — malin jusqu'à preuve du contraire</td></tr>\n          <tr><td><strong>Axillaire</strong></td><td>Membre supérieur, paroi thoracique, glande mammaire</td><td><span class=\"kw-etio\">Bartonellose</span>, <span class=\"kw-etio\">tularémie</span>, <span class=\"kw-alerte\">cancer du sein</span>, BCGite, réaction à une prothèse mammaire</td></tr>\n          <tr><td><strong>Épitrochléenne</strong></td><td>Avant-bras, main</td><td><span class=\"kw-etio\">Syphilis</span>, bartonellose, sarcoïdose, lymphome</td></tr>\n          <tr><td><strong>Inguinale</strong></td><td>Membre inférieur, OGE (hors testicule et prostate), marge anale</td><td>Cancer du territoire de <span class=\"kw-ttt\">drainage</span>, <span class=\"kw-etio\">IST</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">3 — L'<span class=\"kw-bio\">hémogramme</span> oriente la polyadénopathie</h4>\n      <table >\n        <thead><tr><th>Anomalie de l'<span class=\"kw-bio\">hémogramme</span></th><th>Diagnostic évoqué</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Blastes</span> circulants (± anémie, thrombopénie)</td><td><span class=\"kw-alerte\">Leucémie aiguë</span> → myélogramme indispensable</td></tr>\n          <tr><td><span class=\"kw-bio\">Hyperlymphocytose</span> à <span class=\"kw-bio\">lymphocytes</span> matures</td><td><span class=\"kw-def\">Leucémie lymphoïde chronique</span> → immunophénotypage</td></tr>\n          <tr><td><span class=\"kw-bio\">Syndrome mononucléosique</span></td><td><span class=\"kw-etio\">EBV</span>, <span class=\"kw-etio\">CMV</span>, <span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">toxoplasmose</span> → <span class=\"kw-bio\">sérologies</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Lymphoplasmocytes</span> (avec <span class=\"kw-bio\">VS</span> élevée)</td><td><span class=\"kw-def\">Maladie de Waldenström</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Cellules lymphomateuses</span> circulantes</td><td><span class=\"kw-def\">Lymphome</span> avec dissémination sanguine → immunophénotypage</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Signes d'alerte et situations d'<span class=\"kw-alerte\">urgence</span>.</strong>\n        <p><strong>Signes d'alerte</strong> imposant une exploration rapide : signes généraux persistants ; <span class=\"kw-clinique\">adénopathie</span> <span class=\"kw-alerte\">sus-claviculaire</span> (ou jugulo-carotidienne basse) ; caractère <span class=\"kw-alerte\">volumineux, dur, fixé</span> ; augmentation de taille progressive <span class=\"kw-chiffre\">&gt; 3 semaines</span>.</p>\n        <ul>\n          <li><strong><span class=\"kw-clinique\">Masse</span> cervicale obstructive :</strong> compression des voies aériennes supérieures, dysphagie</li>\n          <li><strong><span class=\"kw-clinique\">Masse</span> médiastinale :</strong> <span class=\"kw-clinique\">toux</span>, <span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-alerte\">syndrome cave supérieur</span> (<span class=\"kw-clinique\">œdème</span> facial, <span class=\"kw-clinique\">turgescence jugulaire</span>, circulation collatérale thoracique)</li>\n          <li><strong><span class=\"kw-clinique\">Masse</span> abdominopelvienne :</strong> <span class=\"kw-clinique\">anurie</span> par obstacle urinaire bilatéral, <span class=\"kw-alerte\">invagination intestinale aiguë</span></li>\n          <li><strong>Manifestations systémiques sévères :</strong> <span class=\"kw-clinique\">fièvre</span> élevée mal tolérée, <span class=\"kw-clinique\">pâleur</span>, <span class=\"kw-alerte\">syndrome hémorragique</span>, douleurs osseuses, hépato-<span class=\"kw-clinique\">splénomégalie</span></li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 319 — Lymphome malin · 318 — Leucémie lymphoïde chronique · 315 — Leucémie aiguë · 217 — Syndrome mononucléosique · 320 — Myélome multiple des os</em></p>","frequence":8},{"id":"220-6","rang":"A","rubrique":"Étiologies","titre":"Connaître les étiologies spécifiques des adénites aiguës, subaiguës et chroniques cervicales de l’enfant et de l’adulte","contenu":"<p>Une <span class=\"kw-def\">adénite</span> est une <span class=\"kw-clinique\">adénopathie</span> d'origine <strong><span class=\"kw-etio\">inflammatoire</span> / infectieuse</strong>. Au niveau cervical, les étiologies se classent selon la <strong>chronologie</strong> d'<span class=\"kw-clinique\">évolution</span>.</p>\n      <table >\n        <thead><tr><th>Évolution</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Aiguë</strong></td><td><span class=\"kw-etio\">Adénite</span> et <span class=\"kw-etio\">adénophlegmon</span> à <strong>pyogènes</strong> (<span class=\"kw-etio\">streptocoque A</span>, <span class=\"kw-etio\">S. aureus</span>), sur un foyer <span class=\"kw-etio\">infectieux</span> ORL ou cutané de proximité</td></tr>\n          <tr><td><strong>Subaiguë</strong> — mnémo <strong>TAMISER</strong></td><td><strong>T :</strong> <span class=\"kw-etio\">tuberculose</span>, mycobactéries atypiques<br><strong>A :</strong> <span class=\"kw-etio\">adénophlegmon-angine</span> (foyer oropharyngé, cuir chevelu)<br><strong>M :</strong> <span class=\"kw-etio\">MST</span> — <span class=\"kw-etio\">VIH</span>, syphilis<br><strong>I :</strong> <span class=\"kw-etio\">inoculation</span> — griffes du chat, tularémie<br><strong>S :</strong> <span class=\"kw-etio\">sarcoïdose</span><br><strong>E :</strong> <span class=\"kw-etio\">EBV</span> / MNI (<span class=\"kw-clinique\">adénopathies</span> volontiers postérieures, spinales)<br><strong>R :</strong> <span class=\"kw-etio\">rubéole</span>, brucellose, toxoplasmose (prédominance occipitale)</td></tr>\n          <tr><td><strong>Chronique</strong></td><td><span class=\"kw-etio\">Mycobactéries</span> (<span class=\"kw-def\">tuberculose</span>, atypiques) : <span class=\"kw-clinique\">adénopathies</span> <span class=\"kw-alerte\">« froides »</span>, sans signes inflammatoires, évoluant vers la <span class=\"kw-alerte\">fistulisation</span> (écrouelles)</td></tr>\n        </tbody>\n      </table>\n      <p>Repère anatomique — la <strong><span class=\"kw-def\">classification</span> de Robbins</strong> divise les ganglions cervicaux en <span class=\"kw-chiffre\">6 zones</span> : I (sous-mentale Ia, sous-mandibulaire Ib), II (sous-angulo-mandibulaire, spinale haute), III (jugulo-carotidienne moyenne), IV (sus-claviculaire), V (spinale Va, cervicale transverse Vb), VI (prélaryngée).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 159 — <span class=\"kw-def\">Tuberculose</span> Enfant / Adulte · 169 — <span class=\"kw-etio\">VIH</span> · 217 — Syndrome mononucléosique · 211 — Sarcoïdose</em></p>","frequence":0},{"id":"220-7","rang":"A","rubrique":"Étiologies","titre":"Connaître les principaux diagnostiques différentiels des adénopathies localisées de l’enfant et de l’adulte","contenu":"<p>Toute <span class=\"kw-clinique\">tuméfaction</span> superficielle palpable n'est pas une <span class=\"kw-clinique\">adénopathie</span>. Devant un doute, l'<span class=\"kw-imagerie\">échographie des parties molles</span> aide à trancher.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/220/kyste-amygdaloide-tdm-clinique.png\" alt=\"Kyste amygdaloïde latéro-cervical : coupe TDM montrant la lésion kystique et photographie clinique de la tuméfaction cervicale\" loading=\"lazy\">\n        <figcaption>Kyste amygdaloïde (kyste de la 2ᵉ poche branchiale) : aspect <span class=\"kw-imagerie\">TDM</span> (<span class=\"kw-clinique\">lésion</span> kystique latéro-cervicale) et présentation clinique. Chez l'adulte, toute lésion kystique latéro-cervicale impose d'éliminer une métastase ganglionnaire kystique d'un <span class=\"kw-clinique\">carcinome</span> (cavum, oropharynx). Source : fiche source EDN item 220.</figcaption>\n      </figure>\n\n      <div class=\"obj-distinguer\">\n        <h4>Kyste amygdaloïde <em>(à distinguer)</em></h4>\n        <ul>\n          <li>Kyste <span class=\"kw-def\">congénital lymphoépithélial</span>, par persistance du sinus cervical</li>\n          <li><span class=\"kw-def\">Terrain</span> : <span class=\"kw-clinique\">enfant</span>, <span class=\"kw-clinique\">adulte jeune</span></li>\n          <li><span class=\"kw-clinique\">Tuméfaction</span> superficielle <span class=\"kw-clinique\">rénitente</span>, au bord antérieur du sterno-cléido-mastoïdien</li>\n          <li>Confirmation : <span class=\"kw-imagerie\">échographie</span> / <span class=\"kw-imagerie\">TDM</span> (nature kystique) ; traitement <strong>chirurgical</strong></li>\n        </ul>\n      </div>\n      <div class=\"obj-distinguer\">\n        <h4>Kyste du tractus thyréoglosse <em>(à distinguer)</em></h4>\n        <ul>\n          <li>Persistance d'un canal sur le trajet de migration de la <span class=\"kw-def\">thyroïde</span></li>\n          <li><span class=\"kw-clinique\">Tuméfaction</span> ferme, <strong>médiane</strong>, <span class=\"kw-clinique\">mobile à la déglutition</span> et à la protraction de la langue</li>\n        </ul>\n      </div>\n      <div class=\"obj-distinguer\">\n        <h4>Tumeurs vasculaires battantes <em>(à distinguer)</em></h4>\n        <ul>\n          <li><span class=\"kw-def\">Anévrisme carotidien</span> : tumeur <strong>battante</strong>, expansive, soufflante</li>\n          <li><span class=\"kw-def\">Paragangliome</span> du glomus carotidien : mobile transversalement mais non verticalement ; <span class=\"kw-imagerie\">blush vasculaire</span> en <span class=\"kw-imagerie\">TDM</span> injectée, bifurcation élargie « en lyre »</li>\n        </ul>\n      </div>\n\n      <p><strong>Fausses <span class=\"kw-clinique\">adénopathies</span> cervicales</strong> — mnémo <strong>TABASCO</strong> :</p>\n      <ul>\n        <li><strong>T</strong>hyroïde</li>\n        <li><strong>A</strong>pophyse transverse de l'atlas</li>\n        <li><strong>B</strong>ulbe carotidien <span class=\"kw-etio\">athéromateux</span></li>\n        <li><strong>A</strong>thérome</li>\n        <li><strong>S</strong>alive — ptose des glandes salivaires</li>\n        <li><strong>C</strong>hassaignac — tubercule antérieur du processus transverse de C6</li>\n        <li><strong>O</strong>s hyoïde (grande corne)</li>\n      </ul>\n\n      <table >\n        <thead><tr><th>Localisation</th><th>Diagnostics différentiels</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Latéro-cervicale</strong> — mnémo KAPLANS</td><td><strong>K :</strong> kystes amygdaloïdes<br><strong>A :</strong> anévrisme / <span class=\"kw-clinique\">fistule</span> jugulo-carotidienne<br><strong>P :</strong> paragangliome du glomus carotidien<br><strong>L :</strong> lymphangiome kystique<br><strong>A :</strong> actinomycose<br><strong>N :</strong> neurinome du X<br><strong>S :</strong> salivaires (tumeurs, lithiases submandibulaires)</td></tr>\n          <tr><td><strong>Pré-laryngée</strong></td><td>Kyste du tractus thyréoglosse ; thyroïde ectopique ; laryngocèle</td></tr>\n          <tr><td><strong>Axillaire</strong></td><td><span class=\"kw-def\">Hidrosadénite</span> : sensible, superficielle, adhérente à la peau</td></tr>\n          <tr><td><strong>Inguinale</strong></td><td><span class=\"kw-def\">Hernie inguinale</span> (impulsive à la <span class=\"kw-clinique\">toux</span>) ; kyste du cordon spermatique ; ectopie testiculaire</td></tr>\n          <tr><td><strong>Toutes localisations</strong></td><td><span class=\"kw-def\">Lipome</span> ; <span class=\"kw-clinique\">masse</span> vasculaire pulsatile ; neurinome ; fibrome</td></tr>\n        </tbody>\n      </table>","frequence":2},{"id":"220-8","rang":"A","rubrique":"Étiologies","titre":"Connaître les étiologies fréquentes de l’adénopathie superficielle de l’enfant","contenu":"<div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Chez l'enfant, les <span class=\"kw-etio\">causes infectieuses prédominent</span> très largement.\n      </div>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Infectieuses localisées</strong></td><td><span class=\"kw-etio\">Adénites à pyogènes</span> (<span class=\"kw-etio\">streptocoque</span>, staphylocoque) sur foyer de proximité<br><span class=\"kw-etio\">Tuberculose</span> et mycobactéries atypiques<br>Pathologies d'inoculation : <span class=\"kw-etio\">bartonellose</span> (griffes du chat), tularémie, pasteurellose</td></tr>\n          <tr><td><strong>Infectieuses généralisées</strong></td><td><strong>Virales :</strong> <span class=\"kw-etio\">EBV</span>, <span class=\"kw-etio\">CMV</span>, <span class=\"kw-etio\">VIH</span>, parvovirus B19<br><strong>Parasitaires :</strong> <span class=\"kw-etio\">toxoplasmose</span><br><strong>Bactériennes :</strong> <span class=\"kw-clinique\">fièvre</span> typhoïde, brucellose</td></tr>\n          <tr><td><strong>Tumorales</strong></td><td><strong>Hémopathies malignes :</strong> <span class=\"kw-alerte\">leucémies aiguës</span> (LAL, LAM), <span class=\"kw-def\">lymphome de Hodgkin</span>, lymphome non hodgkinien<br><strong>Métastases :</strong> tumeurs solides</td></tr>\n          <tr><td><strong>Autres causes</strong></td><td><strong>Maladies systémiques :</strong> <span class=\"kw-etio\">maladie de Kawasaki</span>, <span class=\"kw-def\">lupus</span>, sarcoïdose, histiocytoses, déficits immunitaires<br><strong>Médicaments :</strong> certains <span class=\"kw-ttt\">antiépileptiques</span> et <span class=\"kw-ttt\">antibiotiques</span> (rare)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 217 — Syndrome mononucléosique · 159 — <span class=\"kw-def\">Tuberculose</span> Enfant / Adulte · 315 — Leucémie aiguë · 194 — <span class=\"kw-def\">Lupus</span> - SAPL</em></p>","frequence":0},{"id":"220-9","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’indication d’une cytoponction, d’une biopsie, d’une exérèse devant une adénopathie","contenu":"<table >\n        <thead><tr><th>Geste</th><th>Indications et limites</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Cytoponction ganglionnaire</strong></td><td>Utile sur une <span class=\"kw-clinique\">adénopathie</span> <span class=\"kw-etio\">purulente</span> : culture, <span class=\"kw-bio\">PCR</span>, évacuation du pus<br>N'a de valeur <strong>que si positive</strong>, pour orienter vers une origine <span class=\"kw-etio\">néoplasique</span><br><span class=\"kw-alerte\">Ne permet pas l'étude histologique</span> → doit toujours être complétée par une <span class=\"kw-bio\">biopsie</span></td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Biopsie</span> / <span class=\"kw-ttt\">exérèse</span> ganglionnaire</strong></td><td><strong>Indications :</strong> forte suspicion de processus <span class=\"kw-etio\">tumoral</span> dans le territoire de <span class=\"kw-ttt\">drainage</span> ; toute <span class=\"kw-clinique\">adénopathie</span> <span class=\"kw-alerte\">inexpliquée et persistante</span> (notamment <span class=\"kw-chiffre\">&gt; 2 × 2 cm</span> ou évoluant depuis <span class=\"kw-chiffre\">&gt; 1 mois</span>)<br><strong>Modalités :</strong> <span class=\"kw-bio\">biopsie</span> à l'aiguille sous contrôle échographique (anesthésie locale) ou <span class=\"kw-ttt\">exérèse</span> chirurgicale (anesthésie locale, voire générale au bloc opératoire)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Éviter autant que possible l'<span class=\"kw-ttt\">exérèse</span> d'un ganglion <span class=\"kw-alerte\">inguinal</span> ou <span class=\"kw-alerte\">axillaire</span> : geste peu rentable et risque de <span class=\"kw-alerte\">lymphœdème / lymphocèle définitif</span>. La <span class=\"kw-bio\">biopsie</span> à l'aiguille y reste possible ; privilégier un autre site en cas de polyadénopathie.\n      </div>\n      <p>Après le prélèvement : acheminement rapide <strong>à l'état frais</strong> (compresse stérile imbibée de sérum physiologique) et congélation d'une partie du ganglion pour d'éventuelles études complémentaires.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 319 — Lymphome malin</em></p>","frequence":2},{"id":"220-10","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens biologiques à réaliser en première intention dans le cadre d’une adénopathie en fonction du contexte (localisée/généralisée, aiguë/chronique)","contenu":"<p>Devant une <span class=\"kw-clinique\">adénopathie</span> sans cause évidente, le bilan <span class=\"kw-ttt\">biologique</span> de débrouillage s'adapte au <strong>contexte</strong> : <span class=\"kw-clinique\">adénopathie</span> localisée ou généralisée, aiguë ou chronique.</p>\n      <table >\n        <thead><tr><th>Niveau</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Bilan de débrouillage</strong></td><td><span class=\"kw-bio\">NFS</span> avec <span class=\"kw-bio\">frottis sanguin</span><br><span class=\"kw-bio\">VS</span> et <span class=\"kw-bio\">CRP</span></td></tr>\n          <tr><td><strong>Bilan orienté</strong> (polyadénopathie, signes généraux, suspicion d'hémopathie)</td><td><span class=\"kw-bio\">Bilan hépatique</span><br><span class=\"kw-bio\">Électrophorèse des protéines sériques</span><br><span class=\"kw-bio\">LDH</span></td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Sérologies</span></strong></td><td><span class=\"kw-bio\">VIH</span>, <span class=\"kw-bio\">EBV</span>, <span class=\"kw-bio\">CMV</span>, <span class=\"kw-bio\">toxoplasmose</span>, bartonellose, rubéole<br><span class=\"kw-bio\">IDR à la tuberculine</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 212 — <span class=\"kw-bio\">Hémogramme</span> · 169 — <span class=\"kw-etio\">VIH</span> · 217 — Syndrome mononucléosique</em></p>","frequence":1},{"id":"220-11","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens d’imagerie (radiologique et de médecine nucléaire) à pratiquer devant une adénopathie, en fonction du contexte clinique et des examens de première intention","contenu":"<table >\n        <thead><tr><th>Examen</th><th>Indication et apport</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\">Échographie-doppler ganglionnaire</span></td><td>1ʳᵉ intention — caractérise le ganglion, élimine un <span class=\"kw-def\">diagnostic différentiel</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">Radiographie thoracique</span></td><td>Étude du parenchyme pulmonaire, recherche d'<span class=\"kw-clinique\">adénopathies</span> médiastinales</td></tr>\n          <tr><td><span class=\"kw-imagerie\">TDM cervico-thoracique injectée</span></td><td>Avant tout geste invasif sur une <span class=\"kw-clinique\">adénopathie</span> cervicale</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Échographie abdomino-pelvienne</span> + endoscopies digestives</td><td>Si <span class=\"kw-alerte\">ganglion de Troisier</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">TDM thoraco-abdomino-pelvienne</span> injectée</td><td>Si polyadénopathies, signes généraux, <span class=\"kw-def\">syndrome inflammatoire</span> ou anomalie de la <span class=\"kw-bio\">NFS</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">Mammographie</span> + <span class=\"kw-imagerie\">échographie</span> mammaire</td><td>Devant une <span class=\"kw-clinique\">adénopathie</span> axillaire chez la femme</td></tr>\n          <tr><td><span class=\"kw-imagerie\">TEP-TDM au 18FDG</span></td><td>Met en évidence les <span class=\"kw-clinique\">adénopathies</span> hypermétaboliques ; oriente le site du prélèvement anatomopathologique</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"220-12","rang":"B","rubrique":"Examens complémentaires","titre":"Adénopathie superficielle de l’enfant : connaître les examens complémentaires de première intention","contenu":"<table >\n        <thead><tr><th>Situation</th><th>Bilan de 1ʳᵉ intention</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Adénopathie</span> localisée <span class=\"kw-etio\">inflammatoire</span></strong></td><td>Prélèvement <span class=\"kw-bio\">bactériologique</span> d'une porte d'entrée (ORL, stomatologique, cutanée)<br><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">VS</span> / <span class=\"kw-bio\">CRP</span><br>Avis ORL si <span class=\"kw-clinique\">adénopathie</span> cervicale sans cause évidente<br><span class=\"kw-ttt\">Ponction</span> ganglionnaire si réalisable ; <span class=\"kw-bio\">sérologie</span> <span class=\"kw-etio\">bartonellose</span> et IDR selon le contexte</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Adénopathie</span> localisée non <span class=\"kw-etio\">inflammatoire</span></strong> (sans <span class=\"kw-alerte\"><span class=\"kw-def\">critère de</span> gravité</span>)</td><td><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span><br><span class=\"kw-bio\">Sérologies</span> <span class=\"kw-bio\">EBV</span>, <span class=\"kw-bio\">CMV</span>, <span class=\"kw-bio\">toxoplasmose</span>, <span class=\"kw-bio\">parvovirus B19</span><br>Consultation spécialisée si persistance <span class=\"kw-chiffre\">≥ 3 semaines</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Adénopathies</span> disséminées</strong></td><td><span class=\"kw-bio\">Hémogramme</span> + <span class=\"kw-bio\">frottis sanguin</span> = examen clé</td></tr>\n        </tbody>\n      </table>\n      <p>Prise en charge de l'<span class=\"kw-clinique\">adénopathie</span> localisée <span class=\"kw-etio\">inflammatoire</span> : <span class=\"kw-ttt\">antibiothérapie</span> probabiliste par <span class=\"kw-ttt\">amoxicilline + acide clavulanique</span> ; <span class=\"kw-bio\">biopsie</span>-<span class=\"kw-ttt\">exérèse</span> en cas d'échec du traitement.</p>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-ci\">Contre-indication</span> à connaître (HAS).</strong> Devant une <span class=\"kw-clinique\">adénopathie</span> persistante d'origine inconnue, après élimination d'une cause locale ou infectieuse, il ne faut <span class=\"kw-ci\">pas prescrire de corticoïdes</span> avant la <span class=\"kw-bio\">biopsie</span> : la <span class=\"kw-alerte\">corticosensibilité des lymphomes</span> peut modifier l'aspect anatomopathologique et l'imagerie <span class=\"kw-imagerie\">TEP</span>, et faire perdre le diagnostic.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 212 — <span class=\"kw-bio\">Hémogramme</span> · 217 — Syndrome mononucléosique</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p>Deux registres d'<span class=\"kw-alerte\">urgence</span> : <strong>compressif</strong> (<span class=\"kw-clinique\">masse</span> obstructive) et <strong>hématologique</strong> (leucémie aiguë révélée). Hors urgence, le <strong>délai</strong> commande : toute <span class=\"kw-clinique\">adénopathie</span> isolée inexpliquée au-delà de <span class=\"kw-chiffre\">4 à 6 semaines</span> impose la <span class=\"kw-bio\">biopsie</span> ganglionnaire.</p><p><strong><span class=\"kw-clinique\">Masse</span> cervicale obstructive</strong></p><p><span class=\"kw-alerte\">Hospitalisation</span> ; <span class=\"kw-imagerie\">imagerie cervicale</span> ; libération des voies aériennes</p><ul><li><span class=\"kw-alerte\">Compression des voies aériennes supérieures</span></li><li><span class=\"kw-clinique\">Dysphagie</span></li></ul><p><strong><span class=\"kw-clinique\">Masse</span> médiastinale</strong></p><p><span class=\"kw-imagerie\">Radiographie / TDM thoracique</span> ; avis hématologique immédiat</p><ul><li><span class=\"kw-clinique\">Toux</span> prolongée, <span class=\"kw-clinique\">dyspnée</span> (d'effort puis de repos), <span class=\"kw-clinique\">orthopnée</span></li><li><span class=\"kw-alerte\">Syndrome cave supérieur</span> : <span class=\"kw-clinique\">œdème facial</span>, <span class=\"kw-clinique\">turgescence jugulaire</span>, circulation collatérale thoracique</li><li><span class=\"kw-clinique\">Épanchement pleural et/ou péricardique</span></li></ul><p><strong><span class=\"kw-clinique\">Masse</span> abdominopelvienne</strong></p><p><span class=\"kw-imagerie\">Échographie / TDM abdomino-pelvienne</span> en <span class=\"kw-alerte\">urgence</span></p><ul><li><span class=\"kw-alerte\">Anurie</span> par obstacle urinaire bilatéral</li><li><span class=\"kw-alerte\">Invagination intestinale aiguë</span> (<span class=\"kw-clinique\">adénopathies</span> mésentériques)</li><li><span class=\"kw-clinique\">Œdèmes des membres inférieurs</span> (<span class=\"kw-clinique\">adénopathies</span> rétropéritonéales)</li></ul><p><strong>Manifestations systémiques sévères</strong></p><p><span class=\"kw-bio\">Hémogramme + frottis</span> en <span class=\"kw-alerte\">urgence</span> → évoquer une <span class=\"kw-alerte\">leucémie aiguë</span></p><ul><li><span class=\"kw-alerte\">Fièvre élevée mal tolérée</span>, rebelle</li><li><span class=\"kw-clinique\">Pâleur</span>, <span class=\"kw-alerte\">syndrome hémorragique</span>, douleurs osseuses</li><li><span class=\"kw-clinique\">Hépato-splénomégalie</span>, signes neurologiques centraux</li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Signes généraux persistants</span> (symptômes B : <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">sueurs nocturnes</span>, <span class=\"kw-clinique\">amaigrissement</span>)</li><li><span class=\"kw-alerte\">Adénopathie sus-claviculaire</span> ou jugulo-carotidienne basse — <span class=\"kw-alerte\">ganglion de Troisier</span> (gauche) = malin jusqu'à preuve du contraire</li><li>Ganglion <span class=\"kw-alerte\">volumineux, dur, fixé</span> (consistance ligneuse, ballonisation, immobilité aux plans profonds)</li><li><span class=\"kw-alerte\">Augmentation progressive &gt; 3 semaines</span> sans caractère régressif</li><li><span class=\"kw-clinique\">Adénopathie isolée</span> inexpliquée <span class=\"kw-chiffre\">&gt; 4 à 6 semaines</span> → <span class=\"kw-def\">hémopathie lymphoïde</span> jusqu'à preuve du contraire</li><li><span class=\"kw-alerte\">Hypoesthésie de la houppe du menton</span> → atteinte méningée d'une hémopathie maligne</li></ul>","principes":"<p>Pas de traitement de l'<span class=\"kw-clinique\">adénopathie</span> « en soi » : la PEC est <strong>étiologique</strong>. Deux situations dominent — l'<span class=\"kw-etio\">adénite infectieuse</span> (<span class=\"kw-ttt\">antibiothérapie</span>) et l'<span class=\"kw-clinique\">adénopathie suspecte</span> (documentation histologique). Fil rouge : <span class=\"kw-ci\">ne jamais prescrire de corticoïdes avant la biopsie</span>.</p><p><strong>Adénite localisée <span class=\"kw-etio\">inflammatoire</span></strong></p><p><span class=\"kw-ttt\">Biopsie-exérèse</span> si échec de l'<span class=\"kw-ttt\">antibiothérapie</span> (révèle lymphome ou infection résistante)</p><ul><li><span class=\"kw-ttt\">Antibiothérapie</span> probabiliste : <span class=\"kw-ttt\">amoxicilline + acide clavulanique</span> (couvre <span class=\"kw-etio\">streptocoque</span>, <span class=\"kw-etio\">staphylocoque</span>, Pasteurella)</li><li>Adaptation selon le prélèvement <span class=\"kw-bio\">bactériologique</span> de la porte d'entrée</li><li><span class=\"kw-ttt\">Ponction / drainage</span> si <span class=\"kw-clinique\">adénopathie</span> purulente collectée</li></ul><p><strong>Cytoponction ganglionnaire</strong></p><p><span class=\"kw-ci\">Ne permet pas l'étude histologique</span> → toujours complétée par une <span class=\"kw-bio\">biopsie</span></p><ul><li>Utile sur <span class=\"kw-clinique\">adénopathie</span> <span class=\"kw-etio\">purulente</span> : culture, <span class=\"kw-bio\">PCR</span>, évacuation du pus</li><li>Valeur <strong>uniquement si positive</strong> pour orienter vers une origine <span class=\"kw-etio\">néoplasique</span></li></ul><p><strong><span class=\"kw-ttt\">Biopsie</span> / exérèse ganglionnaire</strong></p><p><span class=\"kw-ci\">Éviter l'exérèse inguinale ou axillaire</span> : risque de <span class=\"kw-alerte\">lymphœdème / lymphocèle définitif</span></p><ul><li>Indication : suspicion <span class=\"kw-etio\">tumorale</span>, ou <span class=\"kw-clinique\">adénopathie</span> <span class=\"kw-alerte\">inexpliquée et persistante</span> (<span class=\"kw-chiffre\">&gt; 2 × 2 cm</span> ou évoluant depuis <span class=\"kw-chiffre\">&gt; 1 mois</span>)</li><li><span class=\"kw-ttt\">Biopsie à l'aiguille</span> sous <span class=\"kw-imagerie\">échographie</span> (anesthésie locale) ou <span class=\"kw-ttt\">exérèse chirurgicale</span></li><li>Acheminement <strong>à l'état frais</strong> + congélation d'une partie du ganglion</li></ul><p><strong><span class=\"kw-ci\">Contre-indication</span> majeure (HAS)</strong></p><p><span class=\"kw-ci\">Pas de corticoïdes avant la biopsie</span> : la corticosensibilité des <span class=\"kw-def\">lymphomes</span> fausse l'<span class=\"kw-bio\">anatomopathologie</span> et le <span class=\"kw-imagerie\">TEP</span></p><ul><li><span class=\"kw-clinique\">Adénopathie</span> persistante inexpliquée, après élimination d'une cause locale ou infectieuse</li></ul>","suivi":"<p><strong>Adénite traitée :</strong> <span class=\"kw-def\">réévaluation</span> à <span class=\"kw-chiffre\">12–24 h</span> puis à distance ; <span class=\"kw-bio\">NFS, VS/CRP</span> pour suivre l'<span class=\"kw-clinique\">évolution</span>.<br><strong><span class=\"kw-clinique\">Adénopathie</span> non <span class=\"kw-etio\">inflammatoire</span> :</strong> <span class=\"kw-alerte\">consultation spécialisée</span> si persistance <span class=\"kw-chiffre\">≥ 3 semaines</span> sans diagnostic de certitude.<br><strong>Règle d'or :</strong> tout tableau inexpliqué et prolongé <span class=\"kw-chiffre\">&gt; 4 à 6 semaines</span> impose la <span class=\"kw-bio\">biopsie</span> ganglionnaire (recherche de <span class=\"kw-def\">lymphome</span>, de <span class=\"kw-etio\">tuberculose</span>).</p>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/lymph-node-enlargement","label":"Radiopaedia : Lymph node enlargement"},{"href":"https://www.pinkybone.com/anatomie-aires-ganglionnaires-cervicales/","label":"Anatomie aires ganglionnaires cervicales"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Adénopathie superficielle : signes d'urgence / d'alerte ? — Examen clinique + caractérisation (ADENOPATA) + recherche de masse compressive","detail":"<h4>CAT — <span class=\"kw-clinique\">adénopathie</span> superficielle — Tri : <span class=\"kw-alerte\">urgence</span> → unique / multiple → caractère <span class=\"kw-etio\">inflammatoire</span> / hémogramme</h4>","branches":[{"to":"t-urgence","label":"Oui — masse compressive ou signes systémiques sévères","color":"red"},{"to":"q-nombre","label":"Non — adénopathie sans signe d'urgence","color":"blue"}]},{"id":"t-urgence","kind":"terminal","label":"Urgence — hospitalisation","color":"red","detail":"<h4>Situations d'<span class=\"kw-alerte\">urgence</span></h4><ul><li><span class=\"kw-alerte\">Masse cervicale obstructive</span> : compression des voies aériennes, <span class=\"kw-clinique\">dysphagie</span></li><li><span class=\"kw-alerte\">Masse médiastinale</span> : <span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-alerte\">syndrome cave supérieur</span>, épanchement pleuro-péricardique</li><li><span class=\"kw-alerte\">Masse abdominopelvienne</span> : <span class=\"kw-alerte\">anurie</span> par obstacle bilatéral, <span class=\"kw-alerte\">invagination intestinale aiguë</span></li><li><span class=\"kw-clinique\">Manifestations systémiques sévères</span> : <span class=\"kw-alerte\">fièvre mal tolérée</span>, <span class=\"kw-alerte\">syndrome hémorragique</span>, <span class=\"kw-clinique\">pâleur</span>, hépato-<span class=\"kw-clinique\">splénomégalie</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Hospitalisation</span> ; <span class=\"kw-bio\">hémogramme + frottis</span> en <span class=\"kw-alerte\">urgence</span> ; <span class=\"kw-imagerie\">imagerie</span> de la <span class=\"kw-clinique\">masse</span> ; avis hématologique sans délai</li></ul><h4>Renvoi</h4><ul><li>Item 315 (leucémie aiguë)</li></ul>"},{"id":"q-nombre","kind":"decision","label":"Adénopathie unique ou multiple ? — Localisée (un territoire de drainage) vs polyadénopathie (territoires différents)","branches":[{"to":"q-inflam","label":"Unique / localisée","color":"blue"},{"to":"q-hemo","label":"Multiple — polyadénopathie","color":"blue"}]},{"id":"q-inflam","kind":"decision","label":"Caractère inflammatoire (adénite) ? — Douleur, peau rouge / chaude, ± fistulisation = adénite","branches":[{"to":"t-adenite","label":"Oui — inflammatoire","color":"amber"},{"to":"q-suspect","label":"Non — non inflammatoire","color":"blue"}]},{"id":"t-adenite","kind":"terminal","label":"Adénite infectieuse","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Ganglion douloureux</span>, peau <span class=\"kw-clinique\">rouge / chaude</span>, parfois <span class=\"kw-clinique\">fistulisée</span> ; foyer ORL ou cutané de voisinage</li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Pyogènes</span> : <span class=\"kw-etio\">streptocoque</span> A, S. aureus (le plus fréquent)</li><li><span class=\"kw-etio\">Pathologies d'inoculation</span> : bartonellose (griffes du chat), tularémie, pasteurellose</li><li><span class=\"kw-etio\">Mycobactéries</span> si <span class=\"kw-clinique\">adénopathie</span> « froide » chronique fistulisée</li></ul><h4>Conduite</h4><ul><li>Prélèvement <span class=\"kw-bio\">bactériologique</span> de la porte d'entrée ; <span class=\"kw-bio\">NFS, VS/CRP</span></li><li><span class=\"kw-ttt\">Antibiothérapie</span> : <span class=\"kw-ttt\">amoxicilline + acide clavulanique</span></li><li><span class=\"kw-ttt\">Ponction</span> si <span class=\"kw-clinique\">adénopathie</span> purulente collectée</li></ul><h4>Réflexe EDN</h4><ul><li><span class=\"kw-ttt\">Biopsie-exérèse</span> si échec de l'<span class=\"kw-ttt\">antibiothérapie</span> (démasque un <span class=\"kw-def\">lymphome</span> ou une infection résistante)</li></ul><h4>Renvoi</h4><ul><li>Item 159 (<span class=\"kw-etio\">tuberculose</span>) · Item 217 (syndrome mononucléosique)</li></ul>"},{"id":"q-suspect","kind":"decision","label":"Critère de suspicion ou persistance ? — Dur / fixé / sus-claviculaire, ou évolution prolongée","branches":[{"to":"t-biopsie","label":"Ganglion suspect ou persistant","color":"red"},{"to":"t-surveillance","label":"Ganglion banal, aucun critère","color":"green"}]},{"id":"t-biopsie","kind":"terminal","label":"Suspicion tumorale → biopsie","color":"red","detail":"<h4>Critères suspects</h4><ul><li><span class=\"kw-alerte\">Dur, ligneux, fixé</span>, ballonisation ; <span class=\"kw-alerte\">sus-claviculaire</span> (ganglion de Troisier) ; persistance <span class=\"kw-chiffre\">&gt; 4 à 6 semaines</span></li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-def\">Lymphome</span> (Hodgkin, LNH)</li><li><span class=\"kw-etio\">Métastase</span> d'un cancer du territoire de <span class=\"kw-ttt\">drainage</span></li><li><span class=\"kw-etio\">Mycobactériose</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-imagerie\">TDM cervico-thoracique injectée</span> avant tout geste invasif</li><li><span class=\"kw-ttt\">Biopsie-exérèse ganglionnaire</span> (<span class=\"kw-bio\">histologie</span> + immuno + cytogénétique)</li><li><span class=\"kw-ci\">Pas de corticoïdes avant la biopsie</span> (corticosensibilité des lymphomes)</li></ul><h4>Renvoi</h4><ul><li>Item 319 (lymphome malin)</li></ul>"},{"id":"t-surveillance","kind":"terminal","label":"Surveillance + bilan de débrouillage","color":"green","detail":"<h4>Bilan de 1re intention</h4><ul><li><span class=\"kw-bio\">NFS + frottis</span>, <span class=\"kw-bio\">VS/CRP</span> ; <span class=\"kw-bio\">sérologies</span> <span class=\"kw-bio\">EBV, CMV, toxoplasmose, parvovirus B19</span> ; <span class=\"kw-imagerie\">échographie ganglionnaire</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-def\">Surveillance</span> évolutive ; <span class=\"kw-alerte\">consultation spécialisée si persistance</span> <span class=\"kw-chiffre\">≥ 3 semaines</span> sans diagnostic</li></ul><h4>Renvoi</h4><ul><li>Item 217 (syndrome mononucléosique)</li></ul>"},{"id":"q-hemo","kind":"decision","label":"Hémogramme + frottis (examen clé) ? — L'hémogramme oriente la polyadénopathie","branches":[{"to":"q-hemo-anomalie","label":"Hémogramme anormal","color":"amber"},{"to":"t-poly-normal","label":"Hémogramme normal","color":"blue"}]},{"id":"q-hemo-anomalie","kind":"decision","label":"Quelle anomalie de l'hémogramme ? — Lecture du frottis sanguin","branches":[{"to":"t-la","label":"Blastes ± cytopénies","color":"red"},{"to":"t-llc","label":"Hyperlymphocytose mature","color":"amber"},{"to":"t-mono","label":"Syndrome mononucléosique","color":"blue"},{"to":"t-lympho-circ","label":"Cellules lymphomateuses / lymphoplasmocytes","color":"amber"}]},{"id":"t-la","kind":"terminal","label":"Leucémie aiguë","color":"red","detail":"<h4>Hémogramme</h4><ul><li><span class=\"kw-bio\">Blastes circulants</span> ± <span class=\"kw-bio\">anémie</span>, <span class=\"kw-bio\">thrombopénie</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-bio\">Myélogramme</span> indispensable ; <span class=\"kw-alerte\">urgence</span> hématologique</li></ul><h4>Renvoi</h4><ul><li>Item 315 (leucémie aiguë)</li></ul>"},{"id":"t-llc","kind":"terminal","label":"Leucémie lymphoïde chronique","color":"red","detail":"<h4>Hémogramme</h4><ul><li><span class=\"kw-bio\">Hyperlymphocytose</span> à <span class=\"kw-bio\">lymphocytes</span> matures</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-bio\">Immunophénotypage</span> des <span class=\"kw-bio\">lymphocytes</span> sanguins</li></ul><h4>Renvoi</h4><ul><li>Item 318 (leucémie lymphoïde chronique)</li></ul>"},{"id":"t-mono","kind":"terminal","label":"Virose lymphotrope","color":"blue","detail":"<h4>Hémogramme</h4><ul><li><span class=\"kw-bio\">Syndrome mononucléosique</span></li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">EBV</span>, <span class=\"kw-etio\">CMV</span>, <span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">toxoplasmose</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-bio\">Sérologies</span> ciblées</li></ul><h4>Renvoi</h4><ul><li>Item 217 (syndrome mononucléosique) · Item 169 (<span class=\"kw-etio\">VIH</span>)</li></ul>"},{"id":"t-lympho-circ","kind":"terminal","label":"Dissémination lymphoïde maligne","color":"red","detail":"<h4>Hémogramme</h4><ul><li><span class=\"kw-bio\">Cellules lymphomateuses circulantes</span> ; ou <span class=\"kw-bio\">lymphoplasmocytes</span> avec <span class=\"kw-bio\">VS élevée</span> (Waldenström)</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-bio\">Immunophénotypage</span> ; <span class=\"kw-ttt\">biopsie ganglionnaire</span></li></ul><h4>Renvoi</h4><ul><li>Item 319 (lymphome malin) · Item 320 (myélome multiple des os)</li></ul>"},{"id":"t-poly-normal","kind":"terminal","label":"Polyadénopathie à hémogramme normal","color":"blue","detail":"<h4>Étiologies à évoquer</h4><ul><li><span class=\"kw-etio\">VIH</span> ou <span class=\"kw-etio\">toxoplasmose</span> sans syndrome mononucléosique</li><li><span class=\"kw-etio\">Syphilis secondaire</span>, <span class=\"kw-etio\">brucellose</span>, <span class=\"kw-etio\">leishmaniose viscérale</span></li><li><span class=\"kw-etio\">Sarcoïdose</span>, <span class=\"kw-etio\">lupus</span>, polyarthrite rhumatoïde</li><li><span class=\"kw-etio\">Médicaments</span> (hydantoïnes)</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-bio\">Sérologies</span>, <span class=\"kw-bio\">EPP</span>, <span class=\"kw-bio\">LDH</span>, <span class=\"kw-bio\">bilan hépatique</span>, <span class=\"kw-bio\">IDR</span> ; <span class=\"kw-imagerie\">TDM thoraco-abdomino-pelvienne</span> si signes généraux</li></ul><h4>Réflexe EDN</h4><ul><li><span class=\"kw-bio\">Biopsie ganglionnaire</span> devant tout tableau inexpliqué prolongé <span class=\"kw-chiffre\">&gt; 4 à 6 semaines</span></li></ul><h4>Renvoi</h4><ul><li>Item 169 (<span class=\"kw-etio\">VIH</span>) · Item 211 (sarcoïdose) · Item 194 (lupus)</li></ul>"}]},"cards":[{"i":"0c4aa370493a","n":220,"o":"220-1","u":"Diagnostic positif","t":"Connaître les circonstances de découverte d’une adénopathie superficielle de l’enfant","q":"Quelle est la particularité des polyadénopathies cervicales chez le sujet jeune à retenir en pratique clinique ?","a":"<p>Chez le sujet jeune, des polyadénopathies <strong>cervicales hautes</strong>, <strong>persistantes</strong> et de <strong>petite taille</strong> sont considérées comme <strong>banales</strong>. Ce terrain est fréquemment le siège d'infections virales telles que celles à <strong>EBV</strong>, <strong>CMV</strong> ou <strong>VIH</strong>.</p>"},{"i":"61c7e463b7c7","n":220,"o":"220-1","u":"Diagnostic positif","t":"Connaître les circonstances de découverte d’une adénopathie superficielle de l’enfant","q":"Quelles sont les principales circonstances de découverte d'une adénopathie superficielle chez l'enfant ?","a":"<ul><li><strong>Découverte fortuite</strong> : palpation par l'enfant lui-même ou par les parents (cou, aisselle, aine).</li><li><strong>Examen pédiatrique systématique</strong> : palpation des aires ganglionnaires lors d'une consultation de routine.</li><li><strong>Épisode infectieux</strong> : bilan d'une infection ORL ou cutanée de voisinage.</li><li><strong>Signes généraux</strong> : découverte devant une <strong>fièvre</strong>, un <strong>amaigrissement</strong>, une <strong>asthénie</strong>.</li><li><strong>Complication révélatrice</strong> : phénomène compressif, masse volumineuse.</li></ul>"},{"i":"81c3628d5014","n":220,"o":"220-1","u":"Diagnostic positif","t":"Connaître les circonstances de découverte d’une adénopathie superficielle de l’enfant","q":"Comment est défini cliniquement une adénopathie chez l'enfant ?","a":"<p>Une adénopathie chez l'enfant est définie cliniquement comme un ganglion lymphatique <strong>hypertrophié</strong>, diagnostiqué à la <strong>palpation</strong>. Le seuil de taille considéré comme pathologique est <strong>> 1 cm</strong>, sauf en région inguinale où il est de <strong>> 2 cm</strong>. Ce seuil n'est ni un critère de bénignité ni de malignité.</p>"},{"i":"65fed6160e86","n":220,"o":"220-2","u":"Diagnostic positif","t":"Connaître l’orientation diagnostique d’une adénopathie superficielle de l’enfant","q":"Comment s'oriente-t-on devant une adénopathie superficielle unique et inflammatoire chez l'enfant ?","a":"<p>Une adénopathie unique et inflammatoire oriente le plus souvent vers une <strong>adénite infectieuse bactérienne</strong> sur un foyer de voisinage.</p>"},{"i":"71312ab82cac","n":220,"o":"220-2","u":"Diagnostic positif","t":"Connaître l’orientation diagnostique d’une adénopathie superficielle de l’enfant","q":"Quelles sont les principales causes à explorer devant des adénopathies superficielles multiples chez l'enfant ?","a":"<p>Les causes principales sont :</p><ul><li>Les <strong>causes infectieuses</strong>, nécessitant des sérologies des viroses à tropisme lymphoïde.</li><li>Les <strong>causes tumorales</strong>, nécessitant un hémogramme, un frottis, un éventuel myélogramme et une cytoponction/biopsie.</li></ul>"},{"i":"8ff994ae9ae1","n":220,"o":"220-2","u":"Diagnostic positif","t":"Connaître l’orientation diagnostique d’une adénopathie superficielle de l’enfant","q":"Comment s'oriente-t-on devant une adénopathie superficielle unique et non inflammatoire chez l'enfant ?","a":"<p>Une adénopathie unique et non inflammatoire nécessite un <strong>bilan de débrouillage</strong>, avec un éventuel <strong>avis spécialisé</strong> selon l'évolution.</p>"},{"i":"a94825959153","n":220,"o":"220-2","u":"Diagnostic positif","t":"Connaître l’orientation diagnostique d’une adénopathie superficielle de l’enfant","q":"Quelle est la première étape de l'orientation diagnostique d'une adénopathie superficielle chez l'enfant ?","a":"<p>La première étape est de rechercher la présence de <strong>signes d'urgence</strong>.</p>"},{"i":"eb3becbe15d7","n":220,"o":"220-2","u":"Diagnostic positif","t":"Connaître l’orientation diagnostique d’une adénopathie superficielle de l’enfant","q":"Quelle est la prise en charge initiale en présence de signes d'urgence devant une adénopathie superficielle chez l'enfant ?","a":"<p>Devant des signes d'urgence, la prise en charge implique une <strong>hospitalisation</strong>, une <strong>enquête étiologique</strong> (biologie, imagerie) et une <strong>ponction ou biopsie ganglionnaire</strong>.</p>"},{"i":"f192a80f9f62","n":220,"o":"220-2","u":"Diagnostic positif","t":"Connaître l’orientation diagnostique d’une adénopathie superficielle de l’enfant","q":"Quand doit-on évoquer une hémopathie lymphoïde et réaliser une biopsie ganglionnaire pour une adénopathie isolée chez l'enfant ?","a":"<p>Toute adénopathie isolée n'ayant pas fait sa preuve étiologique au bout de <strong>4 à 6 semaines</strong> doit faire évoquer une <strong>hémopathie lymphoïde</strong> et impose une <strong>biopsie ganglionnaire</strong>.</p>"},{"i":"459a29d85cd0","n":220,"o":"220-3","u":"Diagnostic positif","t":"Connaître l’examen des autres organes lymphoïdes","q":"Quel signe neurologique doit alerter devant une polyadénopathie suspecte et que peut-il évoquer ?","a":"<p>Devant toute polyadénopathie suspecte, la recherche d'une <strong>hypoesthésie de la houppe du menton</strong> est essentielle. Ce signe est très évocateur d'une <strong>atteinte méningée</strong>, particulièrement dans un contexte d'<strong>hémopathie maligne</strong>.</p>"},{"i":"65bb23e31810","n":220,"o":"220-3","u":"Diagnostic positif","t":"Connaître l’examen des autres organes lymphoïdes","q":"Quel examen complémentaire est essentiel en cas d'adénopathie cervicale ?","a":"<p>En cas d'adénopathie cervicale, un <strong>examen ORL/cervicofacial complet</strong> s'impose, incluant :</p><ul><li>une <strong>otoscopie</strong></li><li>une <strong>nasofibroscopie pharyngo-laryngée</strong></li><li>la recherche d'une <strong>porte d'entrée</strong> au niveau des voies aérodigestives supérieures (VADS)</li></ul>"},{"i":"ccfc432c6006","n":220,"o":"220-3","u":"Diagnostic positif","t":"Connaître l’examen des autres organes lymphoïdes","q":"Comment doit-on aborder l'examen des aires ganglionnaires devant une adénopathie superficielle ?","a":"<p>Il convient de réaliser une <strong>palpation systématique</strong> de toutes les aires ganglionnaires afin de préciser le caractère localisé ou diffus de l'adénopathie. Il faut examiner particulièrement :</p><ul><li>les aires <strong>cervicales</strong></li><li>les aires <strong>sus-claviculaires</strong></li><li>les aires <strong>axillaires</strong></li><li>les aires <strong>épitrochléennes</strong></li><li>les aires <strong>inguinales</strong></li></ul>"},{"i":"e371dee26091","n":220,"o":"220-3","u":"Diagnostic positif","t":"Connaître l’examen des autres organes lymphoïdes","q":"Quels sont les autres organes lymphoïdes à examiner en présence d'une ou plusieurs adénopathies ?","a":"<p>Outre les aires ganglionnaires, il faut systématiquement rechercher une atteinte des autres organes lymphoïdes :</p><ul><li>l'<strong>anneau de Waldeyer</strong> (recherche d'une hypertrophie amygdalienne à l'examen de l'oropharynx)</li><li>la <strong>rate</strong> (recherche de splénomégalie)</li><li>le <strong>foie</strong> (recherche d'hépatomégalie associée)</li></ul>"},{"i":"911aef6364ff","n":220,"o":"220-4","u":"Diagnostic positif","t":"Connaître les éléments d’interrogatoire pour l’orientation étiologique","q":"Quels sont les signes généraux (« symptômes B ») à rechercher lors de l'interrogatoire face à des adénopathies superficielles, orientant vers une hémopathie lymphoïde ?","a":"<p>Les signes généraux à rechercher sont :</p><ul><li>La <strong>fièvre</strong> (pouvant aussi évoquer une infection mais parfois absente dans le VIH).</li><li>L'<strong>asthénie</strong>.</li><li>L'<strong>anorexie</strong>.</li><li>L'<strong>amaigrissement</strong>.</li><li>Les <strong>sueurs nocturnes</strong>.</li><li>Les <strong>frissons</strong>.</li><li>Le <strong>prurit généralisé</strong>.</li></ul>"},{"i":"94aa55f31385","n":220,"o":"220-4","u":"Diagnostic positif","t":"Connaître les éléments d’interrogatoire pour l’orientation étiologique","q":"Lors de l'interrogatoire d'un patient présentant des adénopathies superficielles, quels antécédents et expositions doivent être recherchés pour orienter l'enquête étiologique ?","a":"<p>Il convient de rechercher :</p><ul><li>Les <strong>antécédents médicaux</strong> et le <strong>statut vaccinal</strong>.</li><li>Les <strong>traitements en cours</strong>.</li><li>La consommation de <strong>toxiques</strong>.</li><li>Les <strong>conduites sexuelles à risque</strong> (orientant vers les IST comme la syphilis, le chancre mou, la maladie de Nicolas-Favre).</li><li>Le <strong>contact animalier</strong> (chat pour la maladie des griffes du chat, gibier pour la tularémie).</li><li>Les <strong>voyages récents</strong> en zone d'endémie parasitaire (leishmaniose viscérale).</li><li>La <strong>profession ou les loisirs</strong> (chasseur, taxidermiste pour la tularémie).</li></ul>"},{"i":"9a27de940148","n":220,"o":"220-4","u":"Diagnostic positif","t":"Connaître les éléments d’interrogatoire pour l’orientation étiologique","q":"Concernant les adénopathies superficielles, quels éléments de l'interrogatoire en lien avec l'âge peuvent orienter vers une étiologie particulière ?","a":"<p>L'âge du patient est un élément clé :</p><ul><li>Chez le <strong>sujet jeune</strong>, l'orientation se fait vers des <strong>viroses banales</strong> telles que l'EBV, le CMV, ou le VIH.</li><li>Chez le <strong>sujet âgé</strong>, le risque de <strong>cancer</strong> est accru et doit être évoqué.</li></ul>"},{"i":"07048a799070","n":220,"o":"220-6","u":"Étiologies","t":"Connaître les étiologies spécifiques des adénites aiguës, subaiguës et chroniques cervicales de l’enfant et de l’adulte","q":"Quelles sont les principales étiologies des adénites cervicales aiguës chez l'enfant et l'adulte ?","a":"<ul><li>Adénite et adénophlegmon à <strong>pyogènes</strong>, notamment <strong>Streptocoque A</strong> et <strong>Staphylococcus aureus</strong>.</li><li>Elles surviennent généralement sur un <strong>foyer infectieux ORL</strong> ou <strong>cutané</strong> de proximité.</li></ul>"},{"i":"9a01bf208d20","n":220,"o":"220-6","u":"Étiologies","t":"Connaître les étiologies spécifiques des adénites aiguës, subaiguës et chroniques cervicales de l’enfant et de l’adulte","q":"Quelles sont les étiologies à évoquer face à une adénite cervicale subaiguë selon le moyen mnémotechnique TAMISER ?","a":"<ul><li><strong>T</strong> : <strong>Tuberculose</strong>, mycobactéries atypiques.</li><li><strong>A</strong> : <strong>Adénophlegmon-angine</strong> (foyer oropharyngé, cuir chevelu).</li><li><strong>M</strong> : <strong>MST</strong> (VIH, syphilis).</li><li><strong>I</strong> : <strong>Inoculation</strong> (griffe du chat, tularémie).</li><li><strong>S</strong> : <strong>Sarcoïdose</strong>.</li><li><strong>E</strong> : <strong>EBV</strong>/<strong>MNI</strong> (adénopathies volontiers postérieures, spinales).</li><li><strong>R</strong> : <strong>Rubéole</strong>, brucellose, toxoplasmose (prédominance occipitale).</li></ul>"},{"i":"a77771f381b2","n":220,"o":"220-6","u":"Étiologies","t":"Connaître les étiologies spécifiques des adénites aiguës, subaiguës et chroniques cervicales de l’enfant et de l’adulte","q":"Quelle est la principale étiologie des adénopathies cervicales chroniques et ses caractéristiques cliniques ?","a":"<ul><li>Les <strong>mycobactéries</strong> (tuberculose, atypiques) sont une étiologie majeure.</li><li>Ces adénopathies sont souvent dites « <strong>froides</strong> », c'est-à-dire <strong>sans signes inflammatoires</strong> patents, et peuvent évoluer vers la <strong>fistulisation</strong> (écrouelles).</li></ul>"},{"i":"b4505d66e960","n":220,"o":"220-6","u":"Étiologies","t":"Connaître les étiologies spécifiques des adénites aiguës, subaiguës et chroniques cervicales de l’enfant et de l’adulte","q":"Quelle est la définition d'une adénite ?","a":"<p>Une adénite est une adénopathie d'<strong>origine inflammatoire</strong> ou <strong>infectieuse</strong>.</p>"},{"i":"46b4cde5fe75","n":220,"o":"220-7","u":"Étiologies","t":"Connaître les principaux diagnostiques différentiels des adénopathies localisées de l’enfant et de l’adulte","q":"Quels sont les principaux diagnostics différentiels des adénopathies latéro-cervicales, selon le mnémonique KAPLANS ?","a":"<ul><li><strong>K</strong> : Kystes amygdaloïdes</li><li><strong>A</strong> : Anévrisme / fistule jugulo-carotidienne</li><li><strong>P</strong> : Paragangliome du glomus carotidien</li><li><strong>L</strong> : Lymphangiome kystique</li><li><strong>A</strong> : Actinomycose</li><li><strong>N</strong> : Neurinome du X</li><li><strong>S</strong> : Salivaires (tumeurs, lithiases submandibulaires)</li></ul>"},{"i":"cff484b3a0bf","n":220,"o":"220-7","u":"Étiologies","t":"Connaître les principaux diagnostiques différentiels des adénopathies localisées de l’enfant et de l’adulte","q":"Qu'est-ce qu'un kyste amygdaloïde (ou de la 2nde poche branchiale) et quelle est son importance diagnostique chez l'adulte ?","a":"<p>Le kyste amygdaloïde est un <strong>kyste congénital lymphoépithélial</strong> résultant de la persistance du sinus cervical, touchant l'<strong>enfant et l'adulte jeune</strong>. Il se manifeste par une tuméfaction superficielle <strong>rénitente</strong>, située au bord antérieur du <strong>sterno-cléido-mastoïdien</strong>. Chez l'adulte, toute lésion kystique latéro-cervicale impose d'éliminer une <strong>métastase ganglionnaire kystique d'un carcinome</strong> (notamment du cavum ou de l'oropharynx).</p>"},{"i":"f19d21231cfa","n":220,"o":"220-7","u":"Étiologies","t":"Connaître les principaux diagnostiques différentiels des adénopathies localisées de l’enfant et de l’adulte","q":"Comment différencier cliniquement un anévrisme carotidien d'un paragangliome du glomus carotidien parmi les tumeurs vasculaires battantes ?","a":"<ul><li>L'<strong>anévrisme carotidien</strong> est une tumeur <strong>battante, expansive, et soufflante</strong>.</li><li>Le <strong>paragangliome du glomus carotidien</strong> est <strong>mobile transversalement mais non verticalement</strong> et présente un <strong>blush vasculaire</strong> à la TDM injectée avec une bifurcation élargie « en lyre ».</li></ul>"},{"i":"fe5ccd4aa2a9","n":220,"o":"220-7","u":"Étiologies","t":"Connaître les principaux diagnostiques différentiels des adénopathies localisées de l’enfant et de l’adulte","q":"Quelle est la particularité clinique d'un kyste du tractus thyréoglosse chez l'enfant ou l'adulte, et comment évolue-t-il à la déglutition ou à la protraction de la langue ?","a":"<p>Le kyste du tractus thyréoglosse se présente comme une tuméfaction <strong>ferme, médiane</strong>, et est caractérisé par sa <strong>mobilité à la déglutition et à la protraction de la langue</strong>.</p>"},{"i":"6bdd3ae347aa","n":220,"o":"220-8","u":"Étiologies","t":"Connaître les étiologies fréquentes de l’adénopathie superficielle de l’enfant","q":"Quelles sont les étiologies non infectieuses (tumorales, systémiques, médicamenteuses) d'une adénopathie superficielle chez l'enfant ?","a":"<p>Les étiologies non infectieuses d'une adénopathie superficielle chez l'enfant sont :</p><ul><li><strong>Tumorales</strong> : <strong>hémopathies malignes</strong> (<strong>leucémies aiguës</strong> LAL, LAM, <strong>lymphome de Hodgkin</strong>, <strong>lymphome non hodgkinien</strong>) ou <strong>métastases</strong> de tumeurs solides.</li><li><strong>Maladies systémiques</strong> : <strong>maladie de Kawasaki</strong>, <strong>lupus</strong>, <strong>sarcoïdose</strong>, histiocytoses, déficits immunitaires.</li><li><strong>Médicaments</strong> : certains <strong>antiépileptiques</strong> et <strong>antibiotiques</strong> (plus rares).</li></ul>"},{"i":"ae649d6496e6","n":220,"o":"220-8","u":"Étiologies","t":"Connaître les étiologies fréquentes de l’adénopathie superficielle de l’enfant","q":"Quelles sont les étiologies infectieuses localisées fréquentes d'une adénopathie superficielle chez l'enfant ?","a":"<p>Chez l'enfant, les étiologies infectieuses localisées fréquentes d'une adénopathie superficielle incluent :</p><ul><li>Les <strong>adénites à pyogènes</strong> (souvent dues au <strong>streptocoque</strong> ou au <strong>staphylocoque</strong>) sur un foyer de proximité.</li><li>La <strong>tuberculose</strong> et les <strong>mycobactéries atypiques</strong>.</li><li>Les pathologies d'inoculation telles que la <strong>bartonellose</strong> (maladie des griffes du chat), la <strong>tularémie</strong> et la <strong>pasteurellose</strong>.</li></ul>"},{"i":"cf28b1c161c0","n":220,"o":"220-8","u":"Étiologies","t":"Connaître les étiologies fréquentes de l’adénopathie superficielle de l’enfant","q":"Quelles sont les étiologies infectieuses généralisées fréquentes d'une adénopathie superficielle chez l'enfant ?","a":"<p>Les étiologies infectieuses généralisées fréquentes d'une adénopathie superficielle chez l'enfant sont :</p><ul><li>Les infections <strong>virales</strong> : <strong>EBV</strong> (Mononucléose Infectieuse), <strong>CMV</strong>, <strong>VIH</strong>, <strong>parvovirus B19</strong>.</li><li>Les infections <strong>parasitaires</strong> : notamment la <strong>toxoplasmose</strong>.</li><li>Les infections <strong>bactériennes</strong> : comme la <strong>fièvre typhoïde</strong> et la <strong>brucellose</strong>.</li></ul>"},{"i":"06a26dce1ba1","n":220,"o":"220-9","u":"Examens complémentaires","t":"Connaître l’indication d’une cytoponction, d’une biopsie, d’une exérèse devant une adénopathie","q":"Comment un prélèvement ganglionnaire (biopsie ou exérèse) doit-il être acheminé et conservé après le geste ?","a":"<p>Après le prélèvement, il doit être acheminé <strong>rapidement à l'état frais</strong> (sur compresse stérile imbibée de sérum physiologique), et une partie du ganglion doit être <strong>congelée</strong> pour d'éventuelles études complémentaires.</p>"},{"i":"a43c700d95b7","n":220,"o":"220-9","u":"Examens complémentaires","t":"Connaître l’indication d’une cytoponction, d’une biopsie, d’une exérèse devant une adénopathie","q":"Quelles sont les limites d'une cytoponction ganglionnaire dans le diagnostic d'une adénopathie suspecte ?","a":"<p>La cytoponction ganglionnaire <strong>n'a de valeur que si elle est positive</strong> pour orienter vers une origine néoplasique. Elle ne permet <strong>pas l'étude histologique</strong> complète et doit toujours être complétée par une biopsie en cas de suspicion de processus malin.</p>"},{"i":"a749aedacbdd","n":220,"o":"220-9","u":"Examens complémentaires","t":"Connaître l’indication d’une cytoponction, d’une biopsie, d’une exérèse devant une adénopathie","q":"Quel piège doit-on éviter concernant l'exérèse chirurgicale d'une adénopathie ?","a":"<p>Il faut éviter autant que possible l'exérèse d'un <strong>ganglion inguinal ou axillaire</strong> car ce geste est peu rentable et présente un risque de <strong>lymphœdème ou lymphocèle définitif</strong>. La biopsie à l'aiguille est préférable dans ces localisations, ou le prélèvement sur un autre site en cas de polyadénopathie.</p>"},{"i":"c1456c641e7a","n":220,"o":"220-9","u":"Examens complémentaires","t":"Connaître l’indication d’une cytoponction, d’une biopsie, d’une exérèse devant une adénopathie","q":"Dans quel contexte clinique la cytoponction ganglionnaire est-elle particulièrement utile pour l'exploration d'une adénopathie ?","a":"<p>La cytoponction ganglionnaire est utile sur une <strong>adénopathie purulente</strong>. Elle permet alors la culture, la PCR et l'évacuation du pus.</p>"},{"i":"f55aa770003b","n":220,"o":"220-9","u":"Examens complémentaires","t":"Connaître l’indication d’une cytoponction, d’une biopsie, d’une exérèse devant une adénopathie","q":"Quelles sont les indications de la biopsie ou de l'exérèse ganglionnaire pour l'exploration d'une adénopathie ?","a":"<ul><li>Forte suspicion de processus tumoral dans le territoire de drainage.</li><li>Toute adénopathie <strong>inexpliquée et persistante</strong>, notamment si elle mesure <strong>> 2 × 2 cm</strong> ou évolue depuis <strong>> 1 mois</strong>.</li></ul>"}]};